defmodule ForemanAgent.Env.Overlay do
  @moduledoc """
  Generates the two files the agent layers over a repo's devcontainer:

  - a compose overlay that strips published ports, turns off restart
    policies (the agent orders starts after a reboot, once secrets are back
    on tmpfs), labels every service with the environment (and the
    devcontainer as such, with the Foreman feature it's built with), and
    mounts the secrets directory and the Tailscale state volume
  - the devcontainer.json to bring up, with the overlay appended to
    `dockerComposeFile` (as absolute paths)

  The YAML is written by hand: the structure is fixed, every scalar is
  emitted as a JSON string (valid YAML), and compose's `!reset` tag has no
  equivalent in a generic encoder.
  """

  @tailscale_volume "foreman-tailscale"

  @type params :: %{
          optional(:recovery_dir) => Path.t() | nil,
          env_id: String.t(),
          slug: String.t(),
          services: [String.t()],
          devcontainer_service: String.t(),
          secrets_dir: Path.t(),
          tailscale: %{enabled: boolean()},
          feature_version: String.t() | nil
        }

  @spec compose(params()) :: String.t()
  def compose(params) do
    tailscale? = params.tailscale[:enabled] == true

    services =
      Enum.map(params.services, fn service ->
        [
          "  ",
          q(service),
          ":\n",
          "    ports: !reset []\n",
          "    restart: \"no\"\n",
          "    labels:\n",
          "      \"foreman.env_id\": ",
          q(params.env_id),
          "\n",
          "      \"foreman.slug\": ",
          q(params.slug),
          "\n",
          feature_label(service, params),
          "      \"foreman.devcontainer\": ",
          q(if(service == params.devcontainer_service, do: "true", else: "")),
          "\n",
          if(service == params.devcontainer_service,
            do: devcontainer_service(params, tailscale?),
            else: []
          )
        ]
      end)

    volumes = if tailscale?, do: ["volumes:\n  ", q(@tailscale_volume), ": {}\n"], else: []

    IO.iodata_to_binary([
      "# Generated by Foreman for ",
      params.slug,
      ". Rewritten on every start; don't edit.\n",
      "services:\n",
      services,
      volumes
    ])
  end

  # Set when the container is created, which is when its image is built;
  # a container that's reused keeps its labels. Every other service
  # gets an empty one, which overrides any label the repo gives it.
  defp feature_label(service, params) do
    version =
      if service == params.devcontainer_service, do: params[:feature_version] || "", else: ""

    ["      \"foreman.feature_version\": ", q(version), "\n"]
  end

  defp devcontainer_service(params, tailscale?) do
    env =
      [{"FOREMAN_ENV", params.slug}] ++
        if(tailscale?, do: [{"TS_HOSTNAME", params.slug}], else: [])

    [
      "    environment:\n",
      Enum.map(env, fn {k, v} -> ["      ", q(k), ": ", q(v), "\n"] end),
      "    volumes:\n",
      readonly_mount(params.secrets_dir, "/run/foreman"),
      if(params[:recovery_dir],
        do: readonly_mount(params.recovery_dir, recovery_mount()),
        else: []
      ),
      if(tailscale?,
        do: [
          "      - type: volume\n",
          "        source: ",
          q(@tailscale_volume),
          "\n",
          "        target: \"/var/lib/tailscale\"\n"
        ],
        else: []
      )
    ]
  end

  def recovery_mount, do: "/mnt/foreman-recovery"

  defp readonly_mount(source, target) do
    [
      "      - type: bind\n",
      "        source: ",
      q(source),
      "\n",
      "        target: ",
      q(target),
      "\n",
      "        read_only: true\n",
      "        bind:\n",
      "          create_host_path: false\n"
    ]
  end

  defp q(value) when is_binary(value), do: JSON.encode!(value)

  @doc """
  The override devcontainer.json: the repo's config with
  `dockerComposeFile` replaced by absolute paths plus the overlay.
  `initializeCommand` stays: it runs outside the
  containers, which is the environment's own VM.
  """
  @spec override_config(map(), keyword()) :: map()
  def override_config(config, opts) do
    files = Keyword.fetch!(opts, :compose_files) ++ [Keyword.fetch!(opts, :overlay_path)]
    Map.put(config, "dockerComposeFile", files)
  end

  @doc "Options for the Foreman feature, passed with --additional-features."
  @spec feature_options(map()) :: map()
  def feature_options(tailscale), do: %{"tailscale" => tailscale[:enabled] == true}

  def tailscale_volume, do: @tailscale_volume
end
